insert into learn_review_items (
  entity_type, entity_ref, location, claim, category, severity, status, source_hint, notes
) values (
  'QUESTION', 'question:sq-a3-06', 'Advanced · Stage 3, Consent and End-of-Life Ethics, In Depth · Stage Quiz', 'Under HPCSA guidance, when must a practitioner respect a refusal of treatment recorded in a patient''s advance statement?',
  'MEDICAL', 2, 'APPROVED',
  'HPCSA, ''Seeking Patients'' Informed Consent: The Ethical Considerations'', Booklet 4 (revised December 2021, current as at 2026-09-24), reproduced in the Excellence in Deceased Donation course manual (2025), PDF pp.86-102: 3.3.2 material risk; 3.4.1 consent is a continuing dialogue with the patient or next of kin; 3.4.2.2 interpreters; 3.4.2.6 information in manageable amounts, time to reflect; 3.4.2.10 consent is not informed under duress, coercion, manipulation, misrepresentation or mental impairment (e.g. alcohol or drugs); 6.1 no pressure; 6.2 declare conflicts of interest; 8.1.1-8.1.2 presumption of capacity, an irrational choice is not in itself evidence of incapacity; 8.4.2-8.4.3 find out about a written mandate or advance statement; respect a competent refusal that clearly applies and has not been changed; 9.1 best-interests factors, including 9.1.4 third parties'' views of the patient''s preferences and 9.1.5 the least restrictive option; 10.1 consult colleagues and seek a court ruling where disputes cannot be resolved; 15.1 a signed consent form is not sufficient evidence of informed consent', 'Keyed answer and explanation checked against: HPCSA, ''Seeking Patients'' Informed Consent: The Ethical Considerations'', Booklet 4 (revised December 2021, current as at 2026-09-24), reproduced in the Excellence in Deceased Donation course manual (2025), PDF pp.86-102: 3.3.2 material risk; 3.4.1 consent is a continuing dialogue with the patient or next of kin; 3.4.2.2 interpreters; 3.4.2.6 information in manageable amounts, time to reflect; 3.4.2.10 consent is not informed under duress, coercion, manipulation, misrepresentation or mental impairment (e.g. alcohol or drugs); 6.1 no pressure; 6.2 declare conflicts of interest; 8.1.1-8.1.2 presumption of capacity, an irrational choice is not in itself evidence of incapacity; 8.4.2-8.4.3 find out about a written mandate or advance statement; respect a competent refusal that clearly applies and has not been changed; 9